def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    # Gather counts
    cc = dd = cd = dc = 0
    for a, b in history:
        if a == 'C' and b == 'C':
            cc += 1
        elif a == 'D' and b == 'D':
            dd += 1
        elif a == 'C' and b == 'D':
            cd += 1
        else:
            dc += 1

    opp_last = history[-1][1]
    my_last = history[-1][0]

    opp_c = cc + dc   # times opponent cooperated
    opp_d = cd + dd   # times opponent defected
    my_c = cc + cd
    my_d = dc + dd

    # Early detection window
    if n < 4:
        if opp_last == 'D':
            return 'D'
        return 'C'

    # Persistent defector -> defect
    if opp_d >= n - 1 and n >= 5:
        return 'D'

    # Near endgame: convert cooperation into defection payoff
    if n >= 93:
        # Against highly cooperative opponents, defect hard
        if opp_c >= n * 0.65:
            return 'D'
        # Against mostly defecting, keep defecting
        if opp_d > opp_c:
            return 'D'
        # Otherwise cooperate to preserve mutual gains
        return 'C'

    # Occasional exploitation probe against very cooperative, long-run opponents
    if opp_d == 0 and n >= 15:
        # Defect sparingly, then return to cooperation
        if n % 7 == 0:
            return 'D'
        return 'C'

    # Opponent mostly cooperative: cooperate; only retaliate briefly
    if opp_c >= n * 0.7:
        if opp_last == 'D':
            # If opponent defected once recently after long cooperation, likely noise -> retaliate once
            if my_last == 'C':
                return 'D'
            # If both defected last, return to cooperation
            return 'C'
        return 'C'

    # Opponent mostly defects: defect, with rare cooperation probes
    if opp_d >= n * 0.6:
        if rng.random() < 0.92:
            return 'D'
        return 'C'

    # Mixed regime: tit-for-tat with a one-step forgiveness and occasional random break
    if opp_last == 'C':
        # Avoid getting stuck in DD cycles: if we defected last and opp cooperated, cooperate back
        if my_last == 'D':
            return 'C'
        return 'C'

    # opp_last == 'D'
    if my_last == 'D':
        # Mutual defection recently; try to restart cooperation unless opp is serial defector
        recent_opp_def = sum(1 for a, b in history[-5:] if b == 'D')
        if recent_opp_def >= 4:
            return 'D'
        return 'C'

    # We cooperated, opponent defected: retaliate, but avoid overly long feuds
    # Check if opponent has been mostly nice
    if opp_c * 3 >= n * 2:
        # If opponent defection looks isolated, retaliate once then plan to cooperate
        if n >= 2 and history[-2][1] == 'C':
            return 'D'
        if rng.random() < 0.5:
            return 'D'
        return 'C'
    return 'D'
